-- =====================================================================
-- Faculty Management System - FULL DEMO DATA (reset + seed in one run)
-- ICT2132 Mini Project
--
-- WHAT IT DOES
--   1. DELETES ALL DATA in faculty_db (tables are emptied, ids restart at 1)
--   2. Inserts: 1 admin, 7 lecturers, 4 technical officers, 24 undergraduates
--      (18 REGULAR, 3 REPEAT, 3 BATCH_MISSED), the 9 L2-S1 courses,
--      timetable, enrolments, attendance (15 sessions for every theory and
--      practical component), medical records, marks, grades and notices.
--
-- HOW TO RUN (once db/schema.sql has been run at least once, as root):
--     mysql -u root -p < db/seed_data.sql
--   XAMPP (root has no password):   mysql -u root < db/seed_data.sql
--
-- ALL ACCOUNTS USE THE PASSWORD:  12345678   (stored as a BCrypt hash)
--
-- LOGINS
--   admin                          ADMIN
--   lecturer1 .. lecturer7         LECTURER            (1 Lakal, 2 Nuwan, 3 Akila, 4 Sandaruwani,
--                                                        5 Nuwangi, 6 Chamara, 7 Dilani)
--   to1 .. to4                     TECHNICAL_OFFICER
--   student1 .. student24          UNDERGRADUATE       (student n = reg. no. in the table below)
--
-- ATTENDANCE SCENARIOS (same % in every course; eligibility = attendance incl. APPROVED medicals >= 80%)

--   student1  TG/2024/1001  REGULAR       absent 0/15  medicals -  => >80%
--   student2  TG/2024/1002  REGULAR       absent 1/15  medicals -  => >80%
--   student3  TG/2024/1003  REGULAR       absent 0/15  medicals -  => >80%
--   student4  TG/2024/1004  REGULAR       absent 1/15  medicals -  => >80%
--   student5  TG/2024/1005  REGULAR       absent 2/15  medicals -  => >80%
--   student6  TG/2024/1006  REGULAR       absent 2/15  medicals -  => >80%
--   student7  TG/2024/1007  REGULAR       absent 3/15  medicals -  => exactly 80%
--   student8  TG/2024/1008  REGULAR       absent 3/15  medicals -  => exactly 80%
--   student9  TG/2024/1009  REGULAR       absent 3/15  medicals -  => exactly 80%
--   student10 TG/2024/1010  REGULAR       absent 4/15  medicals -  => <80% no medicals
--   student11 TG/2024/1011  REGULAR       absent 5/15  medicals -  => <80% no medicals
--   student12 TG/2024/1012  REGULAR       absent 7/15  medicals -  => <80% no medicals
--   student13 TG/2024/1013  REGULAR       absent 2/15  medicals ['APPROVED', 'APPROVED']  => >80% with medicals
--   student14 TG/2024/1014  REGULAR       absent 2/15  medicals ['APPROVED', 'APPROVED']  => >80% with medicals
--   student15 TG/2024/1015  REGULAR       absent 4/15  medicals ['APPROVED', 'APPROVED']  => <80% raw, >80% with approved medicals
--   student16 TG/2024/1016  REGULAR       absent 4/15  medicals ['APPROVED', 'APPROVED', 'APPROVED']  => <80% raw, >80% with approved medicals
--   student17 TG/2024/1017  REGULAR       absent 6/15  medicals ['APPROVED', 'APPROVED', 'REJECTED']  => <80% with medicals
--   student18 TG/2024/1018  REGULAR       absent 7/15  medicals ['APPROVED', 'APPROVED', 'PENDING', 'PENDING']  => <80% with medicals
--   student19 TG/2023/1004  REPEAT        absent 4/15  medicals ['APPROVED', 'REJECTED']  => exactly 80% with approved medicals
--   student20 TG/2023/1011  REPEAT        absent 2/15  medicals -  => >80%
--   student21 TG/2023/1019  REPEAT        absent 5/15  medicals -  => <80% no medicals
--   student22 TG/2022/1007  BATCH_MISSED  absent 1/15  medicals -  => >80%
--   student23 TG/2022/1015  BATCH_MISSED  absent 3/15  medicals -  => exactly 80%
--   student24 TG/2022/1023  BATCH_MISSED  absent 6/15  medicals ['APPROVED', 'APPROVED', 'APPROVED']  => exactly 80% with approved medicals
-- =====================================================================

USE faculty_db;
SET NAMES utf8mb4;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE grade;
TRUNCATE TABLE marks;
TRUNCATE TABLE attendance;
TRUNCATE TABLE medical_record;
TRUNCATE TABLE enrollment;
TRUNCATE TABLE course_material;
TRUNCATE TABLE timetable;
TRUNCATE TABLE notice;
TRUNCATE TABLE course;
TRUNCATE TABLE admin;
TRUNCATE TABLE lecturer;
TRUNCATE TABLE technical_officer;
TRUNCATE TABLE staff;
TRUNCATE TABLE undergraduate;
TRUNCATE TABLE department;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;

